'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var small = require( './fixtures/python/small_values.json' );
var medium = require( './fixtures/python/medium_values.json' );
var large = require( './fixtures/python/large_values.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var pdf = factory( 1.0, 1.0 );
	t.equal( typeof pdf, 'function', 'returns a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var pdf;
	var y;

	pdf = factory( 1.0, 1.0 );
	y = pdf( NaN );
	t.equal( isnan( y ), true, 'returns expected value' );

	pdf = factory( NaN, 1.0 );
	y = pdf( 0.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	pdf = factory( 1.0, NaN );
	y = pdf( 0.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	pdf = factory( NaN, NaN );
	y = pdf( NaN );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `c <= 0`, the created function always returns `NaN`', function test( t ) {
	var pdf;
	var y;

	pdf = factory( -1.0, 1.0 );
	y = pdf( 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `d <= 0`, the created function always returns `NaN`', function test( t ) {
	var pdf;
	var y;

	pdf = factory( 1.0, -1.0 );
	y = pdf( 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive number for `x` and a valid `alpha` and `beta`, the function returns `NaN`', function test( t ) {
	var pdf;
	var y;

	pdf = factory( 0.5, 0.1 );
	y = pdf( NINF );
	t.equal( isnan( y ), true, 'returns 0' );

	y = pdf( -100.0 );
	t.equal( isnan( y ), true, 'returns 0' );

	y = pdf( -10.0 );
	t.equal( isnan( y ), true, 'returns 0' );

	y = pdf( -1.0 );
	t.equal( isnan( y ), true, 'returns 0' );

	y = pdf( 0.0 );
	t.equal( isnan( y ), true, 'returns 0' );

	t.end();
});

tape( 'the created function evaluates the pdf for `x` given small `c` and `d`', function test( t ) {
	var expected;
	var delta;
	var pdf;
	var tol;
	var c;
	var d;
	var i;
	var x;
	var y;

	expected = small.expected;
	x = small.x;
	c = small.c;
	d = small.d;
	for ( i = 0; i < x.length; i++ ) {
		pdf = factory( c[i], d[i] );
		y = pdf( x[i] );
		if ( y === expected[i] ) {
			t.equal( y, expected[i], 'x: '+x[i]+'. c: '+c[i]+'. d: '+d[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			delta = abs( y - expected[ i ] );
			tol = 2 * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance. x: '+x[ i ]+'. c: '+c[i]+'. d: '+d[i]+'. y: '+y+'. E: '+expected[ i ]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});

